-- City-specific preview stories for the four ordinary bonus-game tours.
-- Existing attempts retain their snapshots; gameplay and record rules stay unchanged.
with stories(skill_code, city_slug, preview_story) as (
  values
  ('speed', 'minsk', 'После войны Минск отстроили заново, с широкими проспектами и большими площадями. На местной арене времени на раскачку мало. Постарайся забить с первых бросков.'),
  ('speed', 'shanghai', 'На набережной Вайтань старые здания смотрят через реку на небоскрёбы Пудуна. После прогулки между двумя берегами выходи на лёд. Здесь медлить нельзя: до конца отсчёта нужно успеть забить.'),
  ('speed', 'sochi', 'В 2014 году Сочи принимал зимнюю Олимпиаду у самого Чёрного моря. Теперь твоя очередь выходить на лёд: держи темп, до сирены нужно успеть забить.'),
  ('speed', 'tolyatti', 'Тольятти вырос вместе с автозаводом, а имя «Лада» прижилось и в хоккее. Разгоняйся с первых бросков. Время здесь лучше тратить на голы.'),
  ('speed', 'moscow', 'На Красной площади часы Спасской башни отбивают время уже несколько столетий. На этой арене свой отсчёт. Успей выполнить цель, прежде чем он закончится.'),
  ('speed', 'nizhny-novgorod', 'В Нижнем Новгороде сходятся Волга и Ока, а над ними стоит старый кремль. Лестниц и подъёмов на прогулке хватало. Теперь проверь, осталось ли сил на быстрый матч.'),
  ('speed', 'cherepovets', 'Череповец стоит на Шексне и давно живёт рядом с металлургическим комбинатом. Твой матч пройдёт быстрее заводской смены. Забей нужные голы до конца отсчёта.'),
  ('speed', 'yaroslavl', 'Ярославлю больше тысячи лет, и старый город всё ещё смотрит на Волгу с высоких берегов. Но на этот матч столько времени не дадут. Начинай забивать с первых секунд.'),
  ('speed', 'kazan', 'В Казанском кремле соседствуют мечеть Кул-Шариф и Благовещенский собор. Город можно рассматривать часами, а твой матч идёт на время. Не затягивай с броском.'),
  ('speed', 'saint-petersburg', 'В Петербурге летняя ночь бывает светлой, а мосты над Невой разводят по расписанию. У твоего выхода на лёд тоже есть срок: успей забить, пока таймер не дошёл до нуля.'),
  ('accuracy', 'astana', 'Астана выросла в столицу посреди степи, где ветер гуляет между высотками. Здесь тебя ждёт матч на точность. Постарайся закончить его с минимумом промахов.'),
  ('accuracy', 'nizhnekamsk', 'Нижнекамск строили в 1960-х вместе с большим нефтехимическим комплексом. За город играет «Нефтехимик». Примерься к воротам: каждый промах ухудшает твой результат.'),
  ('accuracy', 'novosibirsk', 'Новосибирск начинался с железнодорожного моста через Обь. Чтобы соединить берега, строителям нужны были точные расчёты. Тебе хватит верного момента для броска.'),
  ('accuracy', 'vladivostok', 'Во Владивостоке улицы поднимаются на сопки, а мосты тянутся над морскими бухтами. После таких видов ровный лёд кажется передышкой. Используй её, чтобы попасть в ворота.'),
  ('accuracy', 'khabarovsk', 'Хабаровск стоит у Амура, а его хоккейная команда носит имя этой реки. Берега здесь далеко друг от друга. На льду расстояние скромнее, но шайбу всё равно нужно направить точно.'),
  ('accuracy', 'ufa', 'Над Белой в Уфе стоит памятник Салавату Юлаеву. Его имя знают и хоккейные трибуны. Под их шум не торопись с броском: сначала поймай момент, потом отправляй шайбу в ворота.'),
  ('accuracy', 'yekaterinburg', 'Екатеринбург вырос вокруг железоделательного завода на Исети. У старой плотины до сих пор встречаются жители города. Теперь выходи на местный лёд и попробуй закончить матч с высоким процентом попаданий.'),
  ('accuracy', 'omsk', 'Омск начинался с крепости там, где Омь впадает в Иртыш. На арене тоже придётся найти проход в обороне. Дождись удобного момента и бросай.'),
  ('accuracy', 'chelyabinsk', 'В годы войны Челябинск выпускал танки и получил прозвище Танкоград. Хоккей здесь вырос рядом с заводами. На местном льду проверь свою точность: дождись удобного момента и отправляй шайбу в ворота.'),
  ('accuracy', 'magnitogorsk', 'Магнитогорск строили у горы Магнитной ради железной руды. За город играет «Металлург». Проверь точность на местном льду: выбирай момент для каждого броска.'),
  ('marksmanship', 'toronto', 'В Торонто находится Зал хоккейной славы с трофеями и экспонатами об истории игры. Экскурсию оставь на потом. На этой арене очки придётся заработать своими бросками.'),
  ('marksmanship', 'montreal', 'В Монреале в 1875 году сыграли матч, который вошёл в историю как первая организованная игра в хоккей в помещении. С тех пор броски стали хитрее. Попробуй набрать очки за сложные голы.'),
  ('marksmanship', 'boston', 'В 1924 году бостонские «Брюинз» стали первой американской командой в НХЛ. Хоккей здесь давно освоился. Выходи на лёд и ищи бросок, который принесёт больше очков.'),
  ('marksmanship', 'new-york-metro', 'В Нью-Йорке и его окрестностях соседствуют болельщики «Рейнджерс», «Айлендерс» и «Девилз». Поводов поспорить о хоккее хватает. Дай им ещё один: забей гол, который захочется пересмотреть.'),
  ('marksmanship', 'philadelphia', 'В Филадельфии приняли Декларацию независимости, а рядом с Индепенденс-холлом хранится Колокол Свободы. Здесь тебя ждёт матч на меткость. Выбирай сложные моменты для гола, чтобы набрать нужные очки.'),
  ('marksmanship', 'washington', 'В Вашингтоне музеи и памятники тянутся вдоль Национальной аллеи. В 2018 году «Кэпиталз» впервые привезли сюда Кубок Стэнли. Сегодня охота за очками: выбирай сложные моменты для гола.'),
  ('marksmanship', 'pittsburgh', 'В Питтсбурге две реки сходятся в третью, а бывший город сталелитейных заводов болеет за «Пингвинз». Попробуй закончить матч с голом, который захочется повторить. За сложный бросок можно получить больше очков.'),
  ('marksmanship', 'detroit', 'Прозвище Hockeytown закрепилось за Детройтом, городом автомобильных заводов и «Ред Уингз». Здесь есть с кем сравнить бросок. Набери очки и попробуй подняться в местном рейтинге.'),
  ('marksmanship', 'chicago', 'После пожара 1871 года Чикаго отстроился заново и стал городом небоскрёбов. Твоя задача на местном льду скромнее: набрать очки за голы. Начни с первого удачного броска.'),
  ('marksmanship', 'nashville', 'Нэшвилл привык к музыке: на Бродвее выступают группы, а в городе работает Зал славы кантри. На льду поймай свой ритм. Попробуй забить из сложного положения и заработать больше очков.'),
  ('endurance', 'dallas', 'Даллас рос у железнодорожных путей, а позже принял хоккейные «Старз», переехавшие из Миннесоты. Даже в Техасе нашлось место хоккею. На льду держи серию голов до финальной сирены.'),
  ('endurance', 'denver', 'Денвер называют городом на высоте мили: рядом уже видны Скалистые горы. На этой арене темп задаёт таймер. Забивай вовремя и не сбавляй ход до конца матча.'),
  ('endurance', 'salt-lake-city', 'В 2002 году Солт-Лейк-Сити принимал зимнюю Олимпиаду, а в 2024-м здесь появилась команда НХЛ. Сегодня ты выходишь на лёд на весь матч. Следи за временем до следующего обязательного гола.'),
  ('endurance', 'winnipeg', 'Виннипег вырос у слияния Красной реки и Ассинибойна, где веками встречались торговцы. Теперь место встречи у хоккейных бортов. Забивай регулярно, чтобы матч не закончился раньше срока.'),
  ('endurance', 'edmonton', 'В Эдмонтоне Уэйн Гретцки и «Ойлерз» выиграли четыре Кубка Стэнли за пять лет в 1980-х. Твоя серия пока короче. Продержись до конца матча, забивая через короткие промежутки.'),
  ('endurance', 'calgary', 'Каждое лето Калгари встречает участников Стампида, фестиваля с родео. Сегодня держаться придётся на коньках. До следующего гола осталось немного времени, а впереди ещё целый матч.'),
  ('endurance', 'vancouver', 'В Ванкувере море встречается с горами, а парк Стэнли занимает полуостров рядом с центром. Прогулка подождёт. На льду сейчас нужна выдержка: забивай регулярно до конца матча.'),
  ('endurance', 'seattle', 'Космическую иглу в Сиэтле построили к Всемирной выставке 1962 года. На хоккейной арене взгляд лучше держать ниже, на воротах и таймере. Забей, прежде чем время на гол закончится.'),
  ('endurance', 'los-angeles', 'В Лос-Анджелесе снимают кино, а на льду играют «Кингз». У твоего матча тоже будет финал. Пусть им станет сирена, а не истёкшее время на очередной гол.'),
  ('endurance', 'las-vegas', 'В Лас-Вегасе «Голден Найтс» дошли до финала Кубка Стэнли в своём первом сезоне. Твой выход на лёд тоже начинается с нуля. Посмотрим, сколько голов успеешь забить за полный матч.')
)
update bonus_game game
   set preview_story = stories.preview_story,
       preview_revision = game.preview_revision + 1,
       revision = game.revision + 1,
       updated_at = now()
  from stories
 where game.slug = stories.skill_code || '-' || stories.city_slug
   and game.skill_code = stories.skill_code
   and game.status = 'active'
   and game.preview_story is distinct from stories.preview_story;
